
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_p86_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_p86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.002435563778861e-02, -6.902254897015032e-02, -6.758856608101539e-02, -6.554059646344806e-02, -6.262598163582107e-02, -5.850217309666481e-02, -5.273065734914230e-02, -4.483673369529306e-02, -3.460688668188688e-02, -2.289453553906551e-02, -1.307532688086794e-02, -3.942014421757320e-02, -4.622467802900522e-02, -3.387011213681120e-02, -1.786138838962366e-02, -5.765462684100974e-04, 5.960477245947260e-03, -5.652946682889657e-03, -2.271472303813398e-03, -3.222098122602154e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


